GRANT INSERT ON public.project_solar_production TO authenticated;
CREATE POLICY production_project_insert ON public.project_solar_production FOR INSERT TO authenticated WITH CHECK (requested_by = auth.uid() AND EXISTS (SELECT 1 FROM public.user_roles WHERE user_id = auth.uid() AND role IN ('admin', 'engineer')) AND EXISTS (SELECT 1 FROM public.projects p WHERE p.id = project_id AND p.owner_id = project_solar_production.owner_id));
CREATE OR REPLACE FUNCTION public.record_solar_production_history() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN INSERT INTO public.project_change_history(project_id,owner_id,actor_id,action,summary,changes) VALUES (NEW.project_id,NEW.owner_id,NEW.requested_by,'Estimation solaire','Estimation photovoltaïque indicative enregistrée avec paramètres, sources et méthode.',jsonb_build_object('production_id',NEW.id,'production_kwh',NEW.production_kwh,'unit','kWh/an','engine_version',NEW.engine_version)); RETURN NEW; END; $$;
REVOKE ALL ON FUNCTION public.record_solar_production_history() FROM PUBLIC, anon, authenticated;
CREATE TRIGGER solar_production_history AFTER INSERT ON public.project_solar_production FOR EACH ROW EXECUTE FUNCTION public.record_solar_production_history();